import json,numpy as np,collections
rs=[json.loads(s) for s in open('vectors/eval_records.jsonl')]; metrics=json.load(open('vectors/recorded_metrics.json'))
errors=collections.defaultdict(list)
for r in rs:
 z=np.array(r['logits']); y=np.array(r['labels']); n,v=z.shape; e=r['label_smoothing']; p=z-z.max(1,keepdims=True); lp=p-np.log(np.exp(p).sum(1,keepdims=True)); sup=np.flatnonzero(y!=-100)
 candidates={'all':np.arange(n),'supervised':sup,'span':np.arange(sup[0],sup[-1]+1) if len(sup) else [],'prefix_last':np.arange(sup[-1]+1) if len(sup) else [],'suffix_first':np.arange(sup[0],n) if len(sup) else [],'leading_run':np.arange(np.flatnonzero(y==-100)[0] if np.any(y==-100) else n)}
 h=np.zeros(n);h[sup]=-(1-e)*lp[sup,y[sup]]
 for scale in [1,1/v]:
  t=h-e*scale*lp.mean(1)
  for name, inds in candidates.items():
   val=t[inds].sum() if len(inds) else 0.;val=val/len(inds) if r['reduction']=='mean' and len(inds) else val
   errors[(r['count_policy'],'normal' if scale==1 else 'div_V',name)].append(abs(val-metrics[r['id']]))
for key,err in errors.items():
 print(key, 'matched',sum(x<1e-9 for x in err), '/24', 'max_abs',max(err))
PY","max_output_tokens":3000}));

